/// <summary>
/// class <c>METTelemetryPOApprovalStatusInfoEvent</c> is used to log error event whenever purchase order approval status  info event.
/// </summary>
internal final class METTelemetryPOApprovalStatusInfoEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetryPOApprovalStatusInfoEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetryPOApprovalStatusInfoEvent</c> </returns>
public static METTelemetryPOApprovalStatusInfoEvent construct()
{
    return new METTelemetryPOApprovalStatusInfoEvent();
}

/// <summary>
/// Run confirmation journal error event
/// </summary>
/// <param name = "_purchTable"> table <c>PurchTable</c></param>
public static void runTelemetryEvent(PurchTable _purchTable)
{
    METTelemetryPOApprovalStatusInfoEvent pOApprovalStatusEvent = METTelemetryPOApprovalStatusInfoEvent::construct();

    pOApprovalStatusEvent.addRunTimePropertyToAppinsights(_purchTable);

    pOApprovalStatusEvent.processEvent(METTelemetryEventNames::POApprovalStatusEvent);
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_purchTable"> table <c>_purchTable</c> </param>
public void addRunTimePropertyToAppinsights(PurchTable _purchTable)
{     
    this.addRuntimeProperty('PurchaseOrderId', _purchTable.PurchId);
    this.addRuntimeProperty('warehouseId' ,_purchTable.InventLocationId);
    this.addRuntimeProperty('VendorOrderReference', _purchTable.VendorRef);
    this.addRuntimeProperty('VendorAccount', _purchTable.OrderAccount);
    this.addRuntimeProperty('VendorAccount', _purchTable.InventLocationId);
    this.addRuntimeProperty('VendorOrderReference', _purchTable.VendorRef);
    this.addRuntimeProperty('BuyerGroup', _purchTable.ItemBuyerGroupId);
    this.addRuntimeProperty('ApprovalStatus', enum2Str(_purchTable.DocumentState));
}
